/**
 * The Claude Code token-cost standard (docs/COST.md), mechanically enforced.
 *
 *   policy    packages/core/registry/claude.policy.json (the kit's defaults, schema claude-policy) merged with the
 *             project's optional claude.policy.json (`extends: "kit"`, overrides within the schema's bounds)
 *   sync      writes the cost keys of .claude/settings.json and the standard agents .claude/agents/<name>.md
 *             from the policy; keys and files the generator does not own are never touched
 *   check     fails on drift, an agent without model or maxTurns, an over-long CLAUDE.md, a loop script without a budget
 *
 * Ownership: the settings keys in OWNED_SETTINGS (model, effortLevel and three env variables) and every agent file
 * that carries the GENERATED marker. Everything else in settings.json and every other agent is the project's.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { formatProblems } from "@saasreport/core/schema";
import { expand, matchesAny, readText, walk } from "./canon/files.js";

export const POLICY_FILE = "claude.policy.json";
export const SETTINGS_FILE = ".claude/settings.json";
export const AGENTS_DIR = ".claude/agents";
export const GENERATED = "generated by kit claude sync from claude.policy.json; do not edit (kit check claude)";
/** The exact invocation of the kit CLI in this repository: the kit itself, a vendored snapshot, or the installed package. */
export function kitCommand(root, canon) {
  if (existsSync(join(root, "packages/cli/bin/kit.js"))) return "node packages/cli/bin/kit.js";
  if (canon?.vendor?.path) return `node ${canon.vendor.path.replace(/\/$/, "")}/packages/cli/bin/kit.js`;
  return "npx kit";
}
const P = (file, problem) => ({ file, problem });
const isObj = (v) => v != null && typeof v === "object" && !Array.isArray(v);

/** The settings.json keys the generator owns (env keys are nested under env). */
export const OWNED_SETTINGS = ["model", "effortLevel", "env.CLAUDE_CODE_SUBAGENT_MODEL", "env.CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS", "env.CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL"];

export function deepMerge(base, over) {
  if (!isObj(base) || !isObj(over)) return over === undefined ? base : over;
  const out = { ...base };
  for (const [k, v] of Object.entries(over)) out[k] = k in base ? deepMerge(base[k], v) : v;
  return out;
}

/** Effort levels an agent's frontmatter may carry: the schema's $defs.agentEffort (what the docs allow). */
export const agentEfforts = (kit) => kit.byName("claude-policy").$defs.agentEffort.enum;
const completeRef = (kit) => ({ $ref: `${kit.byName("claude-policy").$id}#/$defs/complete` });

/** The effective policy: kit defaults + the project's overrides. { policy, problems }; policy is null when invalid. */
export function loadPolicy(root, kit, file = POLICY_FILE) {
  const schema = kit.byName("claude-policy");
  const defaults = JSON.parse(readFileSync(join(kit.dir, "..", "registry", "claude.policy.json"), "utf8"));
  const problems = formatProblems(kit.validator.validate(defaults, completeRef(kit))).map((m) => P("claude.policy.json (kit defaults)", m));
  let merged = defaults;
  if (existsSync(join(root, file))) {
    let own;
    try { own = JSON.parse(readFileSync(join(root, file), "utf8")); } catch (e) { return { policy: null, problems: [P(file, `not JSON: ${e.message}`)] }; }
    if (own.extends !== "kit") problems.push(P(file, 'a project policy states `"extends": "kit"` and only its overrides'));
    for (const m of formatProblems(kit.validator.validate(own, schema))) problems.push(P(file, m));
    if (!problems.length) merged = deepMerge(defaults, own);
  }
  if (problems.length) return { policy: null, problems };
  const { extends: _x, ...policy } = merged;
  for (const m of formatProblems(kit.validator.validate(policy, completeRef(kit)))) problems.push(P(file, `merged policy: ${m}`));
  const ceiling = policy.agents?.maxTurnsCeiling;
  for (const [name, a] of Object.entries(policy.agents?.standard || {})) {
    if (a.maxTurns > ceiling) problems.push(P(file, `agent ${name}: maxTurns ${a.maxTurns} is over agents.maxTurnsCeiling ${ceiling}`));
    const model = resolveModel(policy, a.model);
    if (!policy.agents.allowedModels.includes(model)) problems.push(P(file, `agent ${name}: model ${model} is not in agents.allowedModels (${policy.agents.allowedModels.join(", ")})`));
  }
  return { policy: problems.length ? null : policy, problems };
}

/** An agent's role (search | subagent) → the model alias. */
export const resolveModel = (policy, role) => (role === "search" ? policy.subagents.searchModel : policy.subagents.model);

/** The owned settings values: { model, effortLevel, env: {…} } (env values are strings, as Claude Code reads them). */
export function desiredSettings(policy) {
  return {
    model: policy.model,
    effortLevel: policy.effort,
    env: {
      CLAUDE_CODE_SUBAGENT_MODEL: policy.subagents.model,
      CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS: String(policy.subagents.maxConcurrent),
      CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL: policy.subagents.promptCacheTtl,
    },
  };
}

/** One standard agent as a .claude/agents file (YAML frontmatter, the generated marker, the prompt). */
export function renderAgent(policy, name, a) {
  const fm = [`name: ${name}`, `description: ${JSON.stringify(a.description)}`, `model: ${resolveModel(policy, a.model)}`, `maxTurns: ${a.maxTurns}`];
  if (a.effort) fm.push(`effort: ${a.effort}`);
  if (a.tools) fm.push(`tools: ${a.tools.join(", ")}`);
  if (a.omitClaudeMd) fm.push("omitClaudeMd: true");
  return `---\n${fm.join("\n")}\n---\n<!-- ${GENERATED} -->\n\n${a.prompt}\n`;
}

export const desiredAgents = (policy) => Object.fromEntries(Object.entries(policy.agents.standard).map(([n, a]) => [`${AGENTS_DIR}/${n}.md`, renderAgent(policy, n, a)]));

/** Frontmatter of an agent file: { fm: { key: value }, body } (scalars; JSON-quoted strings are unquoted). */
export function parseAgent(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(text);
  if (!m) return { fm: null, body: text };
  const fm = {};
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^([A-Za-z][\w-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    let v = kv[2].trim();
    if (/^".*"$/.test(v)) { try { v = JSON.parse(v); } catch { /* not a JSON string literal: the quoted text is kept as written */ } } else if (/^'.*'$/.test(v)) v = v.slice(1, -1);
    fm[kv[1]] = v;
  }
  return { fm, body: m[2] };
}

const readJson = (root, file) => (existsSync(join(root, file)) ? JSON.parse(readFileSync(join(root, file), "utf8")) : null);

/** settings.json with the owned keys set from the policy; every other key kept, in place. */
export function mergeSettings(current, policy) {
  const want = desiredSettings(policy);
  const out = { ...(isObj(current) ? current : {}) };
  out.model = want.model;
  out.effortLevel = want.effortLevel;
  out.env = { ...(isObj(out.env) ? out.env : {}), ...want.env };
  return out;
}

const agentFiles = (root) => walk(root, AGENTS_DIR).filter((f) => f.endsWith(".md") && !f.startsWith(".claude/worktrees/"));

/**
 * Write the policy's settings keys and standard agents. A file that exists without the generated marker is the
 * project's own and is never overwritten. All or nothing: any conflict (or an unreadable settings.json) means nothing
 * is written. `check`: write nothing, report drift. The owned settings keys are the policy's: a different value in
 * settings.json is overwritten and reported in `overwritten` (override it in claude.policy.json, the one source).
 * → { changed: [files], problems, overwritten: [{ key, from, to }] }
 */
export function syncClaude(root, policy, { check = false } = {}) {
  const changed = [], problems = [], overwritten = [], writes = [], removals = [];
  const plan = (file, text) => {
    const cur = existsSync(join(root, file)) ? readFileSync(join(root, file), "utf8") : null;
    if (cur === text) return;
    changed.push(file);
    writes.push([file, text]);
  };
  let current = null;
  try { current = readJson(root, SETTINGS_FILE); } catch (e) { problems.push(P(SETTINGS_FILE, `not JSON: ${e.message}`)); }
  if (!problems.length) {
    const want = desiredSettings(policy);
    for (const [k, v] of Object.entries({ model: want.model, effortLevel: want.effortLevel, ...Object.fromEntries(Object.entries(want.env).map(([e, x]) => [`env.${e}`, x])) })) {
      const have = k.startsWith("env.") ? current?.env?.[k.slice(4)] : current?.[k];
      if (have !== undefined && have !== v) overwritten.push({ key: k, from: have, to: v });
    }
    plan(SETTINGS_FILE, `${JSON.stringify(mergeSettings(current, policy), null, 2)}\n`);
  }
  const want = desiredAgents(policy);
  for (const [file, text] of Object.entries(want)) {
    const cur = existsSync(join(root, file)) ? readFileSync(join(root, file), "utf8") : null;
    if (cur != null && !cur.includes(GENERATED)) { problems.push(P(file, "exists and is the project's own (no generated marker): rename it, or drop the standard agent of that name in claude.policy.json")); continue; }
    plan(file, text);
  }
  for (const file of agentFiles(root)) {
    if (!(file in want) && readText(root, file).includes(GENERATED)) { changed.push(file); removals.push(file); }
  }
  if (!check && !problems.length) {
    for (const [file, text] of writes) { mkdirSync(dirname(join(root, file)), { recursive: true }); writeFileSync(join(root, file), text); }
    for (const file of removals) rmSync(join(root, file));
  }
  return { changed, problems, overwritten };
}

/** The loop budget as shell variables (`eval "$(kit claude budget)"`) or an object. */
export function loopBudget(policy) {
  return { KIT_LOOP_MAX_ITERATIONS: policy.loops.maxIterations, KIT_LOOP_WALL_CLOCK_SECONDS: policy.loops.wallClockMinutes * 60 };
}

/**
 * The JSON for the claude.ai admin console (Organization settings > Claude Code > Managed settings). Only what an
 * organisation should force: the subagent model and cache lifetime, and the effort cap. The main model and the
 * concurrency stay project defaults, because a managed value cannot be raised for one task.
 */
export function managedSettings(policy) {
  const { CLAUDE_CODE_SUBAGENT_MODEL, CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL } = desiredSettings(policy).env;
  return { env: { CLAUDE_CODE_SUBAGENT_MODEL, CLAUDE_CODE_SUBAGENT_PROMPT_CACHE_TTL }, maxEffortLevel: policy.managed.maxEffortLevel };
}

const SCRIPT = /\.(sh|bash|zsh|mjs|cjs|js|ts|py)$/;
const BUDGET = /claude-loop-budget:\s*([^\n]*)/;
/** Paths never scanned: Claude Code's own agent worktrees hold full copies of the repository. */
export const DEFAULT_EXCLUDE = [".claude/worktrees/**"];

/**
 * The code of a script without its comments (and, for shell, without the text of quoted strings), so a comment or an
 * echoed line never counts as a command. `shell`: # comments, quotes emptied; otherwise // and /* *\/ (js) or # (py)
 * comments are dropped and strings kept (a program names its command in a string).
 */
export function codeOf(src, file) {
  const shell = /\.(sh|bash|zsh)$/.test(file), hash = shell || /\.py$/.test(file);
  let out = "", i = 0;
  while (i < src.length) {
    const c = src[i], prev = out[out.length - 1];
    if (c === "\\" ) { out += shell ? " " : src.slice(i, i + 2); i += 2; continue; }
    if (c === "'" || c === '"' || (c === "`" && !shell)) {
      let j = i + 1;
      while (j < src.length && src[j] !== c) j += src[j] === "\\" ? 2 : 1;
      const inner = src.slice(i + 1, j);
      // shell: the text of a string is dropped, but a command substitution inside "…" still runs
      out += shell ? `${c}${c}${c === '"' ? [...inner.matchAll(/\$\(([^)]*)\)/g)].map((m) => `;(${m[1]});`).join("") : ""}` : src.slice(i, j + 1);
      i = j + 1; continue;
    }
    if (hash && c === "#" && (prev === undefined || /[\s;]/.test(prev))) { while (i < src.length && src[i] !== "\n") i++; continue; }
    if (!hash && c === "/" && src[i + 1] === "/") { while (i < src.length && src[i] !== "\n") i++; continue; }
    if (!hash && c === "/" && src[i + 1] === "*") { const e = src.indexOf("*/", i + 2); i = e < 0 ? src.length : e + 2; continue; }
    out += c; i++;
  }
  return out;
}

/** Does the code run `claude -p` (headless), with `claude` in command position? */
export function runsClaude(code, file) {
  if (/\.(sh|bash|zsh)$/.test(file)) {
    const cmd = /(?:^|[;&|(]|\bthen\b|\bdo\b|\belse\b|\$\()[ \t]*(?:\w+=\S*[ \t]+)*(?:(?:npx|exec|command|time|nohup)[ \t]+)*claude\b([^\n;&|]*)/gm;
    for (const m of code.matchAll(cmd)) if (/(?:^|\s)(?:-p|--print)\b/.test(m[1])) return true;
    return false;
  }
  const call = /\b(?:spawn\w*|exec\w*|Popen|run|call|check_output|check_call)\s*\(\s*(?:\[\s*)?(["'`])claude(?:\s([^"'`]*))?\1([^)]*)/g;
  for (const m of code.matchAll(call)) if (/(?:^|\s)(?:-p|--print)\b/.test(m[2] || "") || /["'`](?:-p|--print)["'`]/.test(m[3])) return true;
  return false;
}
const LOOPS = (code, file) => /\b(?:while|until|for)\b|setInterval/.test(code) || /ralph|loop/i.test(basename(file));

/** Scripts that run `claude -p` in a loop under policy.loops.paths: [{ file, src, budget }] (budget: the declared line or null). */
export function loopScripts(root, policy, exclude = DEFAULT_EXCLUDE) {
  const out = [];
  for (const f of expand(root, policy.loops.paths).filter((x) => SCRIPT.test(x) && !matchesAny(x, exclude))) {
    const src = readText(root, f);
    const code = codeOf(src, f);
    if (!runsClaude(code, f) || !LOOPS(code, f)) continue;
    out.push({ file: f, src, budget: BUDGET.exec(src)?.[1].trim() ?? null });
  }
  return out;
}

/** kit check claude: drift, agents, CLAUDE.md length, loop budgets. → { ok, summary, problems } */
export function checkClaude(root, canon, kit) {
  const cfg = canon?.claude || {};
  const { policy, problems } = loadPolicy(root, kit, cfg.policy || POLICY_FILE);
  if (!policy) return { ok: false, configured: true, checked: 0, summary: "policy invalid", problems };
  // 1. settings and the standard agents against the policy (a dry sync: nothing written)
  const dry = syncClaude(root, policy, { check: true });
  const run = `${kitCommand(root, canon)} claude sync`;
  problems.push(...dry.problems);
  for (const f of dry.changed) problems.push(P(f, `drifts from claude.policy.json: run \`${run}\` and commit the result (never hand-edit generated files; to change a value, override it in claude.policy.json)`));
  // 2. every project agent has model and maxTurns, within the policy
  let agents = 0;
  for (const f of agentFiles(root)) {
    agents++;
    const { fm } = parseAgent(readText(root, f));
    if (!fm) { problems.push(P(f, "no YAML frontmatter (name, description, model, maxTurns)")); continue; }
    if (!fm.model) problems.push(P(f, `agent ${fm.name || basename(f)} has no \`model\` (cost-bounded model: ${policy.agents.allowedModels.join(", ")})`));
    else if (!policy.agents.allowedModels.includes(fm.model)) problems.push(P(f, `model ${fm.model} is not allowed (agents.allowedModels: ${policy.agents.allowedModels.join(", ")})`));
    if (fm.maxTurns == null) problems.push(P(f, `agent ${fm.name || basename(f)} has no \`maxTurns\` (1 to ${policy.agents.maxTurnsCeiling})`));
    else if (!/^\d+$/.test(String(fm.maxTurns)) || Number(fm.maxTurns) < 1 || Number(fm.maxTurns) > policy.agents.maxTurnsCeiling) problems.push(P(f, `maxTurns ${fm.maxTurns} must be a whole number from 1 to ${policy.agents.maxTurnsCeiling}`));
    if (fm.effort && !agentEfforts(kit).includes(fm.effort)) problems.push(P(f, `effort ${fm.effort} is not one of ${agentEfforts(kit).join(", ")}`));
  }
  // 3. CLAUDE.md length
  const exclude = [...DEFAULT_EXCLUDE, ...(cfg.exclude || [])];
  const mds = walk(root).filter((f) => /(^|\/)CLAUDE(\.local)?\.md$/.test(f) && !matchesAny(f, exclude));
  for (const f of mds) {
    const n = readText(root, f).split("\n").length - (readText(root, f).endsWith("\n") ? 1 : 0);
    if (n > policy.claudeMd.maxLines) problems.push(P(f, `${n} lines, over the limit of ${policy.claudeMd.maxLines}: move reference material into path-scoped rules (.claude/rules) or skills`));
  }
  // 4. every scripted agent loop declares a budget within the policy
  const loops = loopScripts(root, policy, exclude);
  for (const l of loops) {
    const { iterations, minutes } = Object.fromEntries([...(l.budget || "").matchAll(/(iterations|minutes)=(\S+)/g)].map((m) => [m[1], m[2]]));
    if (l.budget == null) problems.push(P(l.file, "agent loop without a declared budget: add `claude-loop-budget: policy` (and read `kit claude budget`) or `claude-loop-budget: iterations=N minutes=M`"));
    else if (l.budget === "policy") { if (!/kit claude budget/.test(l.src)) problems.push(P(l.file, "`claude-loop-budget: policy` but the script never runs `kit claude budget`, so nothing enforces it")); }
    else if (!/^\d+$/.test(iterations ?? "") || !/^\d+$/.test(minutes ?? "")) problems.push(P(l.file, `unreadable budget "${l.budget}" (use \`policy\` or \`iterations=N minutes=M\`)`));
    else {
      if (Number(iterations) < 1 || Number(iterations) > policy.loops.maxIterations) problems.push(P(l.file, `iterations=${iterations} is outside 1 to ${policy.loops.maxIterations}`));
      if (Number(minutes) < 1 || Number(minutes) > policy.loops.wallClockMinutes) problems.push(P(l.file, `minutes=${minutes} is outside 1 to ${policy.loops.wallClockMinutes}`));
    }
  }
  const s = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;
  return { ok: !problems.length, configured: true, checked: agents + mds.length + loops.length + 1, summary: `${s(agents, "agent")}, ${s(mds.length, "CLAUDE.md file")} (limit ${policy.claudeMd.maxLines}), ${s(loops.length, "loop script")}`, problems };
}
